questionvariables.text:
/* Randomize the angle swept by the searchlight beam, 30° to 120°, steps of 10° */
theta: rand_with_step(30, 120, 10);

/* Randomize the beam's reach (radius) in metres, steps of 5 */
r: rand_with_step(10, 40, 5);

/* pi = 22/7 as used throughout this topic */
Pi_val: 22/7;

r_sq: r^2;

/* Area of the sector (ground illuminated) */
A: (theta/360) * Pi_val * r_sq;
A_2dp: float(decimalplaces(A, 2));
